from collections import Counter
from pathlib import Path

def transform(grid):
    h,w=len(grid),len(grid[0])
    sep_rows=[i for i,row in enumerate(grid) if len(set(row))==1]
    sep_cols=[j for j in range(w) if len({grid[i][j] for i in range(h)})==1]
    # Uniform full lines are the panel dividers.
    row_ranges=[]; start=0
    for i in sep_rows:
        if start<i: row_ranges.append((start,i))
        start=i+1
    if start<h: row_ranges.append((start,h))
    col_ranges=[]; start=0
    for j in sep_cols:
        if start<j: col_ranges.append((start,j))
        start=j+1
    if start<w: col_ranges.append((start,w))
    div_values={grid[i][0] for i in sep_rows}|{grid[0][j] for j in sep_cols}
    counts=Counter(grid[i][j] for i in range(h) for j in range(w) if grid[i][j] not in div_values)
    bg=counts.most_common(1)[0][0]
    panels=[]
    for r0,r1 in row_ranges:
        for c0,c1 in col_ranges:
            score=sum(grid[i][j]!=bg for i in range(r0,r1) for j in range(c0,c1))
            panels.append((score,r0,r1,c0,c1))
    _,sr0,sr1,sc0,sc1=max(panels)
    out=[row[:] for row in grid]
    for _,r0,r1,c0,c1 in panels:
        if (r1-r0,c1-c0)!=(sr1-sr0,sc1-sc0):
            continue
        for i in range(r1-r0):
            for j in range(c1-c0):
                out[r0+i][c0+j]=grid[sr0+i][sc0+j]
    return out

