from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    sep_rows=[i for i,row in enumerate(grid) if len(set(row))==1 and row[0]!=bg]
    sep_cols=[j for j in range(w) if len({grid[i][j] for i in range(h)})==1 and grid[0][j]!=bg]
    def ranges(n, seps):
        out=[]; start=0
        for x in seps:
            if start<x: out.append((start,x))
            start=x+1
        if start<n: out.append((start,n))
        return out
    row_ranges=ranges(h,sep_rows); col_ranges=ranges(w,sep_cols)
    panels=[]
    for r0,r1 in row_ranges:
        for c0,c1 in col_ranges:
            score=sum(grid[i][j]!=bg for i in range(r0,r1) for j in range(c0,c1))
            panels.append((score,r0,r1,c0,c1))
    _,sr0,sr1,sc0,sc1=max(panels)
    out=[row[:] for row in grid]
    for _,r0,r1,c0,c1 in panels:
        if (r1-r0,c1-c0)==(sr1-sr0,sc1-sc0):
            for i in range(r1-r0):
                for j in range(c1-c0):
                    out[r0+i][c0+j]=grid[sr0+i][sc0+j]
    return out
